import{a,_ as l}from"./chunks/npu_3510_hw_arch_sync.ByinXTj7.js";import{_ as e,a as r}from"./chunks/intra_core_parallel_pipeline_execution_timing.BdSPSiwi.js";import{_ as i,o as d,a as _,b as g}from"./app.C41L12d5.js";const I=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核内同步","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync"},{"text":"核内同步能力概述","link":"/api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync_overview.md","filePath":"api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync_overview.md","outlineHeaders":[{"level":2,"title":"为什么需要核内同步","slug":"为什么需要核内同步","link":"#为什么需要核内同步"},{"level":2,"title":"硬件流水类型","slug":"硬件流水类型","link":"#硬件流水类型"},{"level":2,"title":"核内同步分类","slug":"核内同步分类","link":"#核内同步分类"},{"level":2,"title":"什么时候需要开发者手动插入同步","slug":"什么时候需要开发者手动插入同步","link":"#什么时候需要开发者手动插入同步"}],"lastUpdated":1788329934000}'),n={name:"api/SIMD-API/basic_api/sync_control/intra_core_sync/intra_core_sync_overview.md"};function o(c,t,p,M,s,E){return d(),_("div",null,[...t[0]||(t[0]=[g('<div><article class="markdown-body"><h1>核内同步能力概述<span id="ZH-CN_TOPIC_0000002555621170"></span></h1><h2 id="为什么需要核内同步">为什么需要核内同步<span id="zh-cn_topic_0000002542725361_section199075142046"></span><a class="header-anchor" href="#为什么需要核内同步">​</a></h2><p>AI Core内部的执行单元（如MTE2搬运单元、Vector计算单元等）以异步并行的方式运行，在读写同一存储资源时可能存在数据依赖关系。为确保数据一致性及计算正确性，需通过同步控制协调操作时序。</p><div data-filter="910b,A3"><p>针对<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构2201</a>，硬件架构图如下，高亮部分展示了并行执行的计算单元和搬运单元。</p><p><strong>图 1</strong> 架构图<span id="zh-cn_topic_0000002542725361_fig11732135516285"></span><br><img src="'+a+'" alt title="Atlas_A2_A3_硬件架构图"></p></div><div data-filter="950"><p>针对<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构3510</a>，硬件架构图如下，高亮部分展示了并行执行的计算单元和搬运单元。</p><p><strong>图 2</strong> 架构图<span id="zh-cn_topic_0000002542725361_fig31512113433"></span><br><img src="'+l+'" alt title="Ascend_950PR_950DT_硬件架构图"></p></div><p>下图示例描述了一个常见的Vector计算数据流：</p><ol><li>先通过DMA执行单元将数据从Global Memory搬入到Local Memory；</li><li>进行计算；</li><li>然后再通过DMA执行单元将计算结果从Local Memory搬出到Global Memory。</li></ol><p><img src="'+e+'" alt title="Vector_计算_数据流示意图"></p><p>四个执行单元Scalar、Vector、DMA（MTE2）、DMA(MTE3)并行执行，若访问同一片Local Memory，需要同步机制来控制它们的访问时序：保证先搬入Local Memory后再计算，计算完成后再搬出。</p><p><img src="'+r+'" alt title="intra_core_parallel_pipeline_execution_timing"></p><h2 id="硬件流水类型">硬件流水类型<span id="zh-cn_topic_0000002542725361_section1272612276459"></span><a class="header-anchor" href="#硬件流水类型">​</a></h2><p>AI Core内部并行的指令流水类型和解释如下所示：</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>不同的硬件架构，每一种硬件流水类型包含的具体流水会有所差异，详细介绍请参考<a href="../../../../../guide/programming_guide/advanced_programming/hardware_implementation/hardware_implementation.html">硬件实现</a>章节。</p></div><p><strong>表1</strong> 指令流水类型和相关说明</p><table><thead><tr><th>流水类型</th><th>含义</th></tr></thead><tbody><tr><td>PIPE_S</td><td>标量流水线，使用GlobalTensor/LocalTensor的GetValue函数时为此流水</td></tr><tr><td>PIPE_V</td><td>矢量计算流水及部分硬件架构下的L0C Buffer-&gt;UB数据搬运流水</td></tr><tr><td>PIPE_M</td><td>矩阵计算流水</td></tr><tr><td>PIPE_MTE1</td><td>L1 Buffer -&gt;L0A Buffer、L1 Buffer-&gt;L0B Buffer数据搬运流水</td></tr><tr><td>PIPE_MTE2</td><td>GM-&gt;L1 Buffer、GM-&gt;UB等数据搬运流水</td></tr><tr><td>PIPE_MTE3</td><td>UB-&gt;GM、L1 Buffer-&gt;GM等数据搬运流水</td></tr><tr><td>PIPE_FIX</td><td>L0C Buffer-&gt;GM、L0C Buffer -&gt;L1等数据搬运流水</td></tr></tbody></table><h2 id="核内同步分类">核内同步分类<span id="zh-cn_topic_0000002542725361_section2167161594419"></span><a class="header-anchor" href="#核内同步分类">​</a></h2><p>对上述核内并行流水的同步控制分为两种：</p><ul><li><p>多流水同步：同一核内具有数据依赖的不同类型流水指令之间的同步。 <a href="TQueSync_template_params.html">TQueSync</a>类接口和<a href="SetFlag_WaitFlag_ISASI.html">SetFlag/WaitFlag(ISASI)</a>中提供的同步控制接口的区别在于，<a href="SetFlag_WaitFlag_ISASI.html">SetFlag/WaitFlag(ISASI)</a>中的接口标注为ISASI类别，不能保证跨硬件版本兼容；TQueSync类接口可以保证跨硬件版本兼容。 通过SetFlag/WaitFlag接口进行不同流水线间的同步控制。在SetFlag/WaitFlag的指令中，可以指定一对指令流水（源流水与目的流水）先后执行的关系，表示两个指令流水之间完成一组“锁”机制，其作用原理为：</p><ul><li>SetFlag：当源流水的前序指令的所有读写操作都完成之后，当前指令开始执行，并将硬件中的对应标志位设置为1。</li><li>WaitFlag：当目的流水执行到该指令时，如果发现硬件中对应标志位为0，目的流水的后续指令将一直被阻塞；如果发现硬件中对应标志位为1，则将硬件中对应标志位设置为0，同时目的流水的后续指令开始执行。</li></ul><div data-filter="950"><p>Ascend 950PR/Ascend 950DT新增通过<a href="Lock.html">Lock</a>/<a href="Unlock.html">Unlock</a>接口进行不同流水线间的同步控制。通过Lock锁定指定流水（阻塞后续指令），再通过Unlock释放流水，来完成流水间的同步依赖。</p><ul><li>Lock：根据MutexID获取Mutex，若Mutex已被锁定，将阻塞后续指定流水指令队列，直到前序指令中对应MutexID的Mutex被Unlock。</li><li>Unlock：当前流水的前置指令退出后，根据MutexID释放对应Mutex。</li></ul></div></li><li><p>单流水同步：同一核内具有数据依赖的相同类型流水指令之间的同步。</p><ul><li>通过<a href="PipeBarrier_ISASI.html">PipeBarrier</a>接口进行相同流水线间的同步控制。同一流水中虽然指令是顺序执行，但并不意味着后一条指令开始执行时前一条指令执行结束。PipeBarrier指令可以保证前序指令中所有数据读写全部完成，后序指令才开始执行。注意该接口不支持PIPE_S单流水的同步。</li></ul></li></ul><div data-filter="910b,A3"><p>以<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构2201</a>为例，该硬件架构下所有合法的核内同步组合如<a href="#zh-cn_topic_0000002542725361_table13753342164113">表2</a>和<a href="#zh-cn_topic_0000002542725361_table1555712177426">表3</a>所示。其中，&quot;不涉及&quot;表示硬件层面不存在此种同步组合，&quot;暂无应用场景&quot;表示存在此种同步组合，但在实际开发场景中暂不需要使用。</p><p><strong>表2</strong> AIC中所有合法的核内同步组合<span id="zh-cn_topic_0000002542725361_table13753342164113"></span></p><table><thead><tr><th>源流水</th><th>PIPE_S</th><th>PIPE_M</th><th>PIPE_MTE1</th><th>PIPE_MTE2</th><th>PIPE_MTE3</th><th>PIPE_FIX</th></tr></thead><tbody><tr><td>PIPE_S</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td><td>不涉及</td></tr><tr><td>PIPE_M</td><td>不涉及</td><td>PipeBarrier&lt;PIPE_M&gt;()</td><td>SetFlag&lt;M_MTE1&gt;(0)<br>WaitFlag&lt;M_MTE1&gt;(0)</td><td>SetFlag&lt;M_MTE2&gt;(0)<br>WaitFlag&lt;M_MTE2&gt;(0)</td><td>不涉及</td><td>SetFlag&lt;M_FIX&gt;(0)<br>WaitFlag&lt;M_FIX&gt;(0)</td></tr><tr><td>PIPE_MTE1</td><td>不涉及</td><td>SetFlag&lt;MTE1_M&gt;(0)<br>WaitFlag&lt;MTE1_M&gt;(0)</td><td>PipeBarrier&lt;PIPE_MTE1&gt;()</td><td>SetFlag&lt;MTE1_MTE2&gt;(0)<br>WaitFlag&lt;MTE1_MTE2&gt;(0)</td><td>SetFlag&lt;MTE1_MTE3&gt;(0)<br>WaitFlag&lt;MTE1_MTE3&gt;(0)</td><td>SetFlag&lt;MTE1_FIX&gt;(0)<br>WaitFlag&lt;MTE1_FIX&gt;(0)</td></tr><tr><td>PIPE_MTE2</td><td>不涉及</td><td>SetFlag&lt;MTE2_M&gt;(0)<br>WaitFlag&lt;MTE2_M&gt;(0)</td><td>SetFlag&lt;MTE2_MTE1&gt;(0)<br>WaitFlag&lt;MTE2_MTE1&gt;(0)</td><td>PipeBarrier&lt;PIPE_MTE2&gt;()</td><td>SetFlag&lt;MTE2_MTE3&gt;(0)<br>WaitFlag&lt;MTE2_MTE3&gt;(0)</td><td>暂无应用场景</td></tr><tr><td>PIPE_MTE3</td><td>不涉及</td><td>不涉及</td><td>SetFlag&lt;MTE3_MTE1&gt;(0)<br>WaitFlag&lt;MTE3_MTE1&gt;(0)</td><td>SetFlag&lt;MTE3_MTE2&gt;(0)<br>WaitFlag&lt;MTE3_MTE2&gt;(0)</td><td>PipeBarrier&lt;PIPE_MTE3&gt;()</td><td>暂无应用场景</td></tr><tr><td>PIPE_FIX</td><td>不涉及</td><td>SetFlag&lt;FIX_M&gt;(0)<br>WaitFlag&lt;FIX_M&gt;(0)</td><td>SetFlag&lt;FIX_MTE1&gt;(0)<br>WaitFlag&lt;FIX_MTE1&gt;(0)</td><td>暂无应用场景</td><td>暂无应用场景</td><td>PipeBarrier&lt;PIPE_FIX&gt;()</td></tr></tbody></table><p><strong>表3</strong> AIV中所有合法的核内同步组合<span id="zh-cn_topic_0000002542725361_table1555712177426"></span></p><table><thead><tr><th>源流水</th><th>PIPE_S</th><th>PIPE_V</th><th>PIPE_MTE2</th><th>PIPE_MTE3</th></tr></thead><tbody><tr><td>PIPE_S</td><td>不涉及</td><td>SetFlag&lt;S_V&gt;(0)<br>WaitFlag&lt;S_V&gt;(0)</td><td>SetFlag&lt;S_MTE2&gt;(0)<br>WaitFlag&lt;S_MTE2&gt;(0)</td><td>SetFlag&lt;S_MTE3&gt;(0)<br>WaitFlag&lt;S_MTE3&gt;(0)</td></tr><tr><td>PIPE_V</td><td>SetFlag&lt;V_S&gt;(0)<br>WaitFlag&lt;V_S&gt;(0)</td><td>PipeBarrier&lt;PIPE_V&gt;()</td><td>SetFlag&lt;V_MTE2&gt;(0)<br>WaitFlag&lt;V_MTE2&gt;(0)</td><td>SetFlag&lt;V_MTE3&gt;(0)<br>WaitFlag&lt;V_MTE3&gt;(0)</td></tr><tr><td>PIPE_MTE2</td><td>SetFlag&lt;MTE2_S&gt;(0)<br>WaitFlag&lt;MTE2_S&gt;(0)</td><td>SetFlag&lt;MTE2_V&gt;(0)<br>WaitFlag&lt;MTE2_V&gt;(0)</td><td>PipeBarrier&lt;PIPE_MTE2&gt;()</td><td>SetFlag&lt;MTE2_MTE3&gt;(0)<br>WaitFlag&lt;MTE2_MTE3&gt;(0)</td></tr><tr><td>PIPE_MTE3</td><td>SetFlag&lt;MTE3_S&gt;(0)<br>WaitFlag&lt;MTE3_S&gt;(0)</td><td>SetFlag&lt;MTE3_V&gt;(0)<br>WaitFlag&lt;MTE3_V&gt;(0)</td><td>SetFlag&lt;MTE3_MTE2&gt;(0)<br>WaitFlag&lt;MTE3_MTE2&gt;(0)</td><td>PipeBarrier&lt;PIPE_MTE3&gt;()</td></tr></tbody></table></div><h2 id="什么时候需要开发者手动插入同步">什么时候需要开发者手动插入同步<a class="header-anchor" href="#什么时候需要开发者手动插入同步">​</a></h2><p>TPipe-TQue框架编程范式和毕昇编译器均支持自动同步，可减少开发者手动插入同步的工作量，但部分场景下仍需开发者手动完成。详细说明请参考<a href="key_features.html">自动同步</a>。</p></article></div>',1)])])}const S=i(n,[["render",o]]);export{I as __pageData,S as default};
